module uart_tx(clk,rst,start,tx_data_in,tx,tx_active,done_tx);
import mut_def::*;
parameter clk_freq = 50000000; // 50 MHz
parameter baud_rate = 19200; //bits per second
input clk,rst;
input start;
input [7:0] tx_data_in;
output tx;
output tx_active;
output logic done_tx;

//////////////////////////! i could mutate the baud to do some mis match 

// Mutation 6: double the divider count, reducing the baud rate by half.
localparam integer clock_divide = m6 ? ((clk_freq * 2) / baud_rate)
                                      : (clk_freq / baud_rate);

enum bit [2:0]{ tx_IDLE = 3'b000,
                tx_START = 3'b001,
				tx_DATA = 3'b010,
	        	tx_STOP = 3'b011,
				tx_DONE = 3'b100 
			} tx_STATE,				tx_NEXT;   //tx_STATE for the current state, tx_NEXT for the next one
					 
// Counter width supports the longest combination: doubled divider (m6) and
// three bit-period STOP interval (m11).
localparam integer MAX_CLOCK_DIVIDE = (2 * clk_freq) / baud_rate;
localparam integer CLK_DIV_WIDTH = $clog2((3 * MAX_CLOCK_DIVIDE) + 1);
logic [CLK_DIV_WIDTH-1:0] clk_div_reg, clk_div_next; // Current and next bit-cycle counters.
logic [7:0]         tx_data_reg,			tx_data_next; // tx_data_reg saves data_in, to send correct data even data_in is changed
logic               tx_out_reg,			    tx_out_next; //saves the value of the current bit at tx
logic [2:0]         index_bit_reg,			index_bit_next; //determines which bit is currently transmitted and the next one

assign tx_active = (tx_STATE == tx_DATA); // if current state is tx_DATA, tx_active bit will be = one
assign tx = tx_out_reg;


generate
    // Mutation selection is performed at elaboration time.
    // Bit order: {m0, m1, m2, m3, m4}
    // m5 does not affect this sequential block; it is implemented in the
    // combinational generate case below. The 5'b10000 branch selects m0.
    case ({m0, m1, m2, m3, m4})

        5'b00000: begin : gen_00000
            // Normal implementation
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    index_bit_reg <= 0;
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00001: begin : gen_00001
            // Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    // Mutation 4: index_bit_reg is not reset.
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00010: begin : gen_00010
            // Mutation 3: omit tx_out_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    // Mutation 3: tx_out_reg is not reset.
                    tx_data_reg <= 0;
                    index_bit_reg <= 0;
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00011: begin : gen_00011
            // Mutation 3: omit tx_out_reg reset + Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    // Mutation 3: tx_out_reg is not reset.
                    tx_data_reg <= 0;
                    // Mutation 4: index_bit_reg is not reset.
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00100: begin : gen_00100
            // Mutation 2: omit clk_div_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    // Mutation 2: clk_div_reg is not reset.
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    index_bit_reg <= 0;
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00101: begin : gen_00101
            // Mutation 2: omit clk_div_reg reset + Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    // Mutation 2: clk_div_reg is not reset.
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    // Mutation 4: index_bit_reg is not reset.
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00110: begin : gen_00110
            // Mutation 2: omit clk_div_reg reset + Mutation 3: omit tx_out_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    // Mutation 2: clk_div_reg is not reset.
                    // Mutation 3: tx_out_reg is not reset.
                    tx_data_reg <= 0;
                    index_bit_reg <= 0;
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b00111: begin : gen_00111
            // Mutation 2: omit clk_div_reg reset + Mutation 3: omit tx_out_reg reset + Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk) begin
                if (rst) begin
                    tx_STATE <= tx_IDLE;
                    // Mutation 2: clk_div_reg is not reset.
                    // Mutation 3: tx_out_reg is not reset.
                    tx_data_reg <= 0;
                    // Mutation 4: index_bit_reg is not reset.
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b01000: begin : gen_01000
            // Mutation 1: asynchronous reset event control
            always_ff @(posedge clk or negedge rst) begin
                if (!rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    index_bit_reg <= 0;
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b01001: begin : gen_01001
            // Mutation 1: asynchronous reset event control + Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk or negedge rst) begin
                if (!rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    // Mutation 4: index_bit_reg is not reset.
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
                    index_bit_reg <= index_bit_next;
                end
            end
        end

        5'b01010: begin : gen_01010
            // Mutation 1: asynchronous reset event control + Mutation 3: omit tx_out_reg reset
            always_ff @(posedge clk or negedge rst) begin
                if (!rst) begin
                    tx_STATE <= tx_IDLE;
