                end
            end
        end

        5'b01011: begin : gen_01011
            // Mutation 1: asynchronous reset event control + Mutation 3: omit tx_out_reg reset + Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk or negedge rst) begin
                if (!rst) begin
                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    // Mutation 3: tx_out_reg is not reset.
                    tx_data_reg <= 0;
