        5'b01111: begin : gen_01111
            // Mutation 1: asynchronous reset event control + Mutation 2: omit clk_div_reg reset + Mutation 3: omit tx_out_reg reset + Mutation 4: omit index_bit_reg reset
            always_ff @(posedge clk or negedge rst) begin
