                    tx_STATE <= tx_IDLE;
                    clk_div_reg <= 0;
                    tx_out_reg <= 0;
                    tx_data_reg <= 0;
                    // Mutation 0: initialize index to 7 for reverse bit order.
                    index_bit_reg <= 3'd7;
                end
                else begin
                    tx_STATE      <= tx_NEXT;
                    clk_div_reg   <= clk_div_next;
                    tx_out_reg    <= tx_out_next;
                    tx_data_reg   <= tx_data_next;
